        this.nextOpacity = this.number("\u0412 \u043c\u0438\u0440\u0435: \u044f\u0440\u043a\u043e\u0441\u0442\u044c \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0439 \u0441\u0442\u0440\u043e\u043a\u0438", 35.0, 0.0, 100.0, 5.0, "%");
        this.nextOpacity.visibleWhen(() -> false);
        this.add((Setting)((Setting)new NumberSetting("\u0412 \u043c\u0438\u0440\u0435: \u043d\u0435\u043f\u0440\u043e\u0437\u0440\u0430\u0447\u043d\u043e\u0441\u0442\u044c \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0439 \u0441\u0442\u0440\u043e\u043a\u0438", 35.0, 0.0, 100.0, 5.0).unit("%").bind(this.nextOpacity::get, this.nextOpacity::set)).desc("100% \u2014 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u043f\u043b\u043e\u0442\u043d\u0430\u044f; \u0441\u0442\u0430\u0440\u044b\u0435 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f."));
        this.renderDistance = this.number("\u0412 \u043c\u0438\u0440\u0435: \u0434\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0432\u0438\u0434\u0438\u043c\u043e\u0441\u0442\u0438", 28.0, 6.0, 80.0, 1.0, " \u0431\u043b.");
